// counter считает вызовы функций, обёрнутых через wrap
// counter :: () -> Object
const counter = () => {
  let calls = 0
  return {
    wrap: (fn) => (...args) => {
      calls += 1
      return fn(...args)
    },
    calls: () => calls,
  }
}

